SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for syu_ble_level_tsl
-- ----------------------------
DROP TABLE IF EXISTS `syu_ble_level_tsl`;
CREATE TABLE `syu_ble_level_tsl`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `industry_scene_id` int(0) NULL DEFAULT NULL COMMENT '行业场景ID',
  `level_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'LEVEL_1 / LEVEL_2 / LEVEL_3',
  `tsl_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '该级别下所有点位及权限的 TSL JSON',
  `ts_create_time` bigint(0) NOT NULL COMMENT '创建时间戳(ms)',
  `ts_update_time` bigint(0) NOT NULL COMMENT '更新时间戳(ms)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_scene_level`(`industry_scene_id`, `level_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '蓝牙级别 TSL 配置' ROW_FORMAT = Dynamic;

